import { createMapStoreSidebar } from './map-store-sidebar.js';

const FOCUS_STALE_MS = 30000;

function hashToIndex(str, len) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash = hash & hash;
  }
  return Math.abs(hash) % len;
}

/**
