@layer base {
  * {
    @apply border-border;
  }
  html, body, #app {
    height: 100%;
    margin: 0;
    padding: 0;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Map Entry Row */
.map-entry-row {
  background: var(--task-surface);
  border: 1px solid var(--task-border);
  border-radius: 12px;
  padding: 12px 24px;
  transition: box-shadow 0.15s ease;
}
.map-entry-row:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}
.map-entry-row:hover .map-action-hover {
  opacity: 1;
}
.map-entry-row input:focus {
  outline: 2px solid rgb(1, 108, 221);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Helper Text Animation */
@keyframes pulse-subtle {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.animate-pulse-subtle {
  animation: pulse-subtle 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
